/// Display name for an item id, or a placeholder when the table is absent.
#[cfg(feature = "gamedata")]
pub fn item_name_of(id: u16) -> alloc::string::String {
    crate::gamedata::ITEM_NAME_LIST
        .get(id as usize)
        .map(|s| alloc::string::ToString::to_string(*s))
        .unwrap_or_else(|| alloc::format!("(unknown {})", id))
}

/// Display name for an item id, or a placeholder when the table is absent.
#[cfg(not(feature = "gamedata"))]
pub fn item_name_of(id: u16) -> alloc::string::String {
    alloc::format!("#{}", id)
}

// ---------------------------------------------------------------------------
// The one rule the pick lists move by
// ---------------------------------------------------------------------------

/// How far [◀] / [▶] move a pick list: ten rows. [▲] / [▼] move one.
///
/// The item picker, the decoration picker and the skill picker all move
/// through pick_move, and the two-stage bulk add steps its number through
/// pick_step_count with the same shape, so no route can end up with a
/// different answer to the same key. The console layer turns its shoulders
/// into the same pair instead of scrolling on its own, which is what used to
/// make one key do one thing on one route and another thing on the next.
pub const PICK_STEP: usize = 10;

/// Highest item id any picker offers.
///
/// The id range is a save-format fact, so it stays even in a build without the
/// compiled name table (the table is a feature; the ids are the format).
#[cfg(feature = "gamedata")]
pub const PICK_LAST_ITEM_ID: usize = crate::gamedata::LAST_ITEM_ID;
#[cfg(not(feature = "gamedata"))]
pub const PICK_LAST_ITEM_ID: usize = 2990;

/// One direction key against a list of n rows.
///
/// Returns true when the key was one of the four, so a caller can answer them
/// in one place and keep its own match for the rest.
fn pick_move(cursor: &mut usize, n: usize, key: Key) -> bool {
    if n == 0 {
        // An empty list still swallows the keys: a cursor that points at
        // nothing must not be moved, and the screen must stay usable.
        *cursor = 0;
        return matches!(key, Key::Up | Key::Down | Key::Left | Key::Right);
    }
    match key {
        Key::Up => *cursor = (*cursor + n - 1) % n,
        Key::Down => *cursor = (*cursor + 1) % n,
        Key::Left => *cursor = (*cursor).saturating_sub(PICK_STEP),
        Key::Right => *cursor = (*cursor + PICK_STEP).min(n - 1),
        _ => return false,
    }
    true
}

/// One direction key against a number: [▲] / [▼] step one, [◀] / [▶] step
/// PICK_STEP.
///
/// This is the pick lists' rule applied to the one number a picker owns (the
/// count of the bulk add), so the big step is on the same key pair everywhere.
fn pick_step_count(value: &mut u16, lo: u16, hi: u16, key: Key) -> bool {
    let step: i32 = match key {
        Key::Up => 1,
        Key::Down => -1,
        Key::Right => PICK_STEP as i32,
        Key::Left => -(PICK_STEP as i32),
        _ => return false,
    };
    *value = (*value as i32 + step).clamp(lo as i32, hi as i32) as u16;
    true
}

/// The needle a filter compares with: trimmed, and without the leading '#'.
fn filter_needle(text: &str) -> alloc::string::String {
    let t = text.trim();
    let t = t.strip_prefix('#').unwrap_or(t);
    t.to_lowercase()
}

/// Does a name answer a needle (already lowercased)?
///
/// A prefix match would need the user to remember the start of the name; the
/// game's own names put the useful word in the middle (回復薬グレート), so this
/// is a substring test. The cheap direct test answers the Japanese case
/// without allocating; the lowercased one only runs when it has to, which is
/// what makes "attack" find "Attack Up".
pub fn name_matches(name: &str, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    name.contains(needle) || name.to_lowercase().contains(needle)
}

/// Does the decimal spelling of an id contain the needle?
///
/// Used when this build cannot name an item: the picker then searches the id,
/// so a user who knows the number is not locked out. Written without an
/// allocation because the list is rebuilt on every frame the picker is open.
fn id_digits_contain(id: usize, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    let needle = needle.as_bytes();
    if !needle.iter().all(|b| b.is_ascii_digit()) {
        return false;
    }
    let mut digits = [0u8; 20];
    let mut n = id;
    let mut len = 0;
    loop {
        digits[len] = b'0' + (n % 10) as u8;
        n /= 10;
        len += 1;
        if n == 0 || len == digits.len() {
            break;
        }
    }
    if needle.len() > len {
        return false;
    }
    // The digits were written least significant first, so the decimal
    // spelling is digits[len - 1 - k].
    (0..=len - needle.len()).any(|start| {
        (0..needle.len()).all(|k| digits[len - 1 - (start + k)] == needle[k])
    })
}

/// Item ids a filter keeps, in id order.
///
/// names is the compiled name table, or None for a build that has none: then
/// the needle is matched against the decimal id instead of the name, so the
/// picker still narrows (and the screen says which of the two it is doing).
pub fn filter_item_ids_in(needle: &str, names: Option<&[&str]>) -> Vec<u16> {
    let needle = filter_needle(needle);
    let mut out = Vec::new();
    for id in 1..=PICK_LAST_ITEM_ID {
        let hit = match names {
            Some(list) => list
                .get(id)
                .map(|name| name_matches(name, &needle))
                .unwrap_or(false),
            None => id_digits_contain(id, &needle),
        };
        if hit {
            out.push(id as u16);
        }
    }
    out
}

/// Every decoration id the name table knows, empty socket (0) excluded.
pub fn decoration_ids() -> Vec<u16> {
    #[cfg(feature = "gamedata")]
    {
        // JWL_I_DS[0] is 0 ("(None)"), which the picker offers separately.
        crate::gamedata::JWL_I_DS
            .iter()
            .filter(|id| **id > 0 && **id <= u16::MAX as i32)
            .map(|id| *id as u16)
            .collect()
    }
    #[cfg(not(feature = "gamedata"))]
    {
        Vec::new()
    }
}

/// Display name for a decoration id (2638 + k), or a placeholder.
///
/// JWL_I_DS says which ids are decorations rather than computing 2638 + k
/// (the table is not dense), and the Japanese item table - which carries the
/// same ids - gives the name the game shows. JWL_NAMES is the English list and
/// is only the fallback.
pub fn decoration_name_of(id: u16) -> alloc::string::String {
    if id == 0 {
        return String::from("なし");
    }
    #[cfg(feature = "gamedata")]
    {
        if let Some(i) = crate::gamedata::JWL_I_DS.iter().position(|v| *v == id as i32) {
            if let Some(name) = crate::gamedata::ITEM_NAME_LIST.get(id as usize) {
                if !name.is_empty() {
                    return alloc::string::ToString::to_string(*name);
                }
            }
            if let Some(name) = crate::gamedata::JWL_NAMES.get(i) {
                return alloc::string::ToString::to_string(*name);
            }
        }
    }
    alloc::format!("#{}", id)
}

// ---------------------------------------------------------------------------
// Equipment names, for the picker the ID row opens
// ---------------------------------------------------------------------------
//
// The names are the game's own: crate::equipnames carries the two tables the
// box already prints from (weapons indexed by type and id, armour indexed by
// series * 5 + part), and gamedata carries the talisman list. Nothing new is
// written down here, so the name on a picker row and the name in the box
// cannot disagree - they are the same string.
//
// The measurement the picker is built around: 1,606 named weapons over the 14
// types the box stores, and 6,435 named armour pieces over the five parts. The
// old ID row made the user count through those with [◀] / [▶].

/// The weapon types in box order: 7..=21 without 12, the hole the JP weapon
/// numbering leaves (see equip::type_name).
pub const WEAPON_KINDS: [u8; 14] = [7, 8, 9, 10, 11, 13, 14, 15, 16, 17, 18, 19, 20, 21];
/// The five armour parts, in the order the form cycles them.
pub const ARMOR_KINDS: [u8; 5] = [1, 2, 3, 4, 5];
/// The talisman, the only kind of its family.
pub const TALISMAN_KINDS: [u8; 1] = [6];
/// Which half of the box a name pick is looking through.
///
/// A scope, not a kind: the 1,606 weapons are one list whichever of the 14
/// types the form happens to be on, and the type is a filter inside it. That
/// is what makes "検索: 大剣（137件）" and "全 1,606件" the same list.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EquipScope {
    /// The 14 weapon types (1,606 names).
    Weapons,
    /// The five armour parts (6,435 names).
    Armor,
    /// The talisman list.
    Talismans,
    /// The whole box: the new-record form's picker.
    ///
    /// A new record starts on kind 1 (a piece of armour), so a list scoped by
    /// the form's own kind could only ever offer armour: creating a weapon
    /// meant walking the 種別 row to a weapon kind first - up to fourteen
    /// presses - and only then opening the list. A pick carries both halves
    /// ([EquipChoice]), so the new form opens the whole box and one pick is
    /// the type and the id together.
    All,
}

impl EquipScope {
    /// The scope a record of this type belongs to.
    ///
    /// An unknown type (a corrupt record, or one of the palico kinds the box
    /// never holds) is listed with the weapons rather than refused: the picker
    /// must always have a list, and the form is where the type is corrected.
    pub fn of_kind(kind: u8) -> Self {
        match kind {
            1..=5 => EquipScope::Armor,
            6 => EquipScope::Talismans,
            _ => EquipScope::Weapons,
        }
    }

    /// The word the header uses for this half of the box.
    pub fn label(self) -> &'static str {
        match self {
            EquipScope::Weapons => "武器",
            EquipScope::Armor => "防具",
            EquipScope::Talismans => "護石",
            EquipScope::All => "全種",
        }
    }

    /// The kinds inside this scope, in the game's own type order.
    pub fn kinds(self) -> &'static [u8] {
        match self {
            EquipScope::Weapons => &WEAPON_KINDS,
            EquipScope::Armor => &ARMOR_KINDS,
            EquipScope::Talismans => &TALISMAN_KINDS,
            EquipScope::All => &crate::equip::BOX_KINDS,
        }
    }
}

/// One row of a name pick: a type and an id.
///
/// Both halves are needed - id 40 is 爆砕の大剣 as a 大剣 and something else as
/// a 太刀 - so a picked row writes both back into the form.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EquipChoice {
    /// Equipment type, 1..=21 (see equip::type_name).
    pub kind: u8,
    /// Weapon, armour or talisman id.
    pub id: u16,
}

impl EquipChoice {
    /// The id as the screens write it: "0x28".
    ///
    /// Hexdigits, not decimal, because that is the spelling the box's ID rows
    /// print; the decimal number the game's own menus show is not written
    /// anywhere in this interface.
    pub fn hex(self) -> String {
        format!("0x{:02X}", self.id)
    }

    /// "爆砕の大剣  0x28": the name first, the id beside it.
    pub fn label(self) -> String {
        format!("{}  {}", self.name(), self.hex())
    }

    /// The game's name for this row, or "-" when no table can name it.
    pub fn name(self) -> &'static str {
        equip_choice_name(self.kind, self.id)
    }
}

/// The name one (kind, id) pair carries, out of the compiled tables.
///
/// The indexing is equip::name's: a weapon id indexes its own type's table, an
/// armour id is a series (the part is the low digit of `series * 5 + part`),
/// and the talisman has a list of its own. The picker and the box therefore
/// read the same row.
pub fn equip_choice_name(kind: u8, id: u16) -> &'static str {
    use crate::equipnames::{ARMOR_NAMES, WEAPON_NAMES};
    match kind {
        1..=5 => {
            let part = (kind - 1) as usize;
            ARMOR_NAMES.get(id as usize * 5 + part).copied().unwrap_or("-")
        }
        7..=21 => {
            let t = match kind as usize - 7 {
                5 => return "(未使用)",
                n => n,
            };
            WEAPON_NAMES
                .get(t)
                .and_then(|tbl| tbl.get(id as usize))
                .copied()
                .unwrap_or("-")
        }
        6 => {
            #[cfg(feature = "gamedata")]
            {
                crate::gamedata::EQUIP_TALISMAN_NAMES
                    .get(id as usize)
                    .copied()
                    .unwrap_or("-")
            }
            #[cfg(not(feature = "gamedata"))]
            {
                "-"
            }
        }
        _ => "-",
    }
}

/// Is there a name table for this scope in this build?
///
/// The weapons and the armour are compiled in unconditionally (crate::equipnames
/// is not behind a feature); the talismans come from gamedata. A build without
/// them still gets the picker - it searches ids - which is the fallback the
/// header names.
pub fn equip_names_available(scope: EquipScope) -> bool {
    match scope {
        // "装備なし" is the first row of every weapon table, so a table that
        // names nothing at all has length 0.
        EquipScope::Weapons => crate::equipnames::WEAPON_NAMES
            .iter()
            .any(|t| t.len() > 1),
        EquipScope::Armor => crate::equipnames::ARMOR_NAMES.len() > 5,
        EquipScope::Talismans => {
            #[cfg(feature = "gamedata")]
            {
                !crate::gamedata::EQUIP_TALISMAN_NAMES.is_empty()
            }
            #[cfg(not(feature = "gamedata"))]
            {
                false
            }
        }
        // The whole box names its rows when any of its three halves can.
        EquipScope::All => {
            equip_names_available(EquipScope::Weapons)
                || equip_names_available(EquipScope::Armor)
                || equip_names_available(EquipScope::Talismans)
        }
    }
}

/// Every (kind, id) the name tables of one scope hold, in type then id order.
///
/// The rows are the tables themselves, id 0 included: the measured volume of
/// the game's own data is 1,606 weapons over 14 types and 6,435 armour pieces
/// over five parts, and those are the numbers the header counts. A hole in a
/// table (the game leaves "装備なし" where a series has no piece) is a row too,
/// because id 0 is a value the record can hold and the box prints it.
///
/// The list is rebuilt per frame, so it carries no names - a row looks its name
/// up when it is drawn (EquipChoice::name).
pub fn equip_choices(scope: EquipScope) -> Vec<EquipChoice> {
    // The whole box is the two lists the 装備BOX screen can hold, one after
    // the other, in the order [crate::equip::BOX_KINDS] names: one list, one
    // cursor, one rule for the arrows. The talismans are not in it - the box
    // cannot create one (equipops::create_in_box) and its list does not show
    // one (equip_rows), so offering them here would be a pick that writes a
    // record the screen it returns to cannot see.
    if scope == EquipScope::All {
        let mut out = equip_choices(EquipScope::Weapons);
        out.extend(equip_choices(EquipScope::Armor));
        return out;
    }
    let mut out = Vec::new();
    match scope {
        EquipScope::Weapons => {
            for &kind in WEAPON_KINDS.iter() {
                let Some(table) = crate::equipnames::WEAPON_NAMES.get(kind as usize - 7) else {
                    continue;
                };
                for id in 0..table.len() {
                    out.push(EquipChoice {
                        kind,
                        id: id as u16,
                    });
                }
            }
        }
        EquipScope::Armor => {
            // ARMOR_NAMES is series * 5 + part, so the series count is a fifth
            // of it and the part picks the row inside the block.
            let series = crate::equipnames::ARMOR_NAMES.len() / 5;
            for &kind in ARMOR_KINDS.iter() {
                let part = (kind - 1) as usize;
                for s in 0..series {
                    // A table short of 5 * series rows names nothing for the
                    // tail rather than pointing past its end.
                    if crate::equipnames::ARMOR_NAMES.get(s * 5 + part).is_none() {
                        continue;
                    }
                    out.push(EquipChoice {
                        kind,
                        id: s as u16,
                    });
                }
            }
        }
        EquipScope::Talismans => {
            #[cfg(feature = "gamedata")]
            {
                for id in 0..crate::gamedata::EQUIP_TALISMAN_NAMES.len() {
                    out.push(EquipChoice {
                        kind: 6,
                        id: id as u16,
                    });
                }
            }
        }
        // Answered by the three lists above, before the match: the whole box is
        // not a fourth table, it is the three of them one after the other.
        EquipScope::All => {}
    }
    out
}

/// Does an id's hex spelling contain the needle (already lowercased)?
///
/// The fallback search and the "type the id you can see" case both go through
/// this: the row prints 0x28, so 28 has to find it. The "0x" a user may copy
/// from the screen is dropped by pick_needle, so both spellings work.
fn hex_digits_contain(id: u16, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    if !needle.bytes().all(|b| b.is_ascii_hexdigit()) {
        return false;
    }
    let mut digits = [0u8; 4];
    let mut n = id;
    let mut len = 0;
    loop {
        digits[len] = b"0123456789abcdef"[(n & 0xF) as usize];
        n >>= 4;
        len += 1;
        if n == 0 || len == digits.len() {
            break;
        }
    }
    if needle.len() > len {
        return false;
    }
    // The digits are least significant first, so the spelling is the reverse.
    (0..=len - needle.len()).any(|start| {
        (0..needle.len())
            .all(|k| digits[len - 1 - (start + k)] == needle.as_bytes()[k])
    })
}

/// Does one row answer the needle (already lowercased and trimmed)?
///
/// Three things answer it, and all three are on the screen: the name, the type
/// ("大剣" finds all 137 of them), and the hex id the row prints. A build with
/// no name table for the scope answers the id alone, which is the fallback the
/// header announces.
pub fn equip_choice_matches(choice: EquipChoice, needle: &str) -> bool {
    if needle.is_empty() {
        return true;
    }
    if equip_names_available(EquipScope::of_kind(choice.kind)) {
        let name = choice.name();
        // Same test name_matches makes, with the lowercased half kept for the
        // names that can actually have a capital in them: this runs over 6,435
        // rows every frame the picker is open, and a Japanese name has no case
        // to fold.
        if name.contains(needle)
            || (name.bytes().any(|b| b.is_ascii_uppercase())
                && name.to_lowercase().contains(needle))
        {
            return true;
        }
        // The type name answers "大剣" for all 137 of them. It is Japanese (or
        // "(未使用)"), so there is no case to fold here either.
        if crate::equip::type_name(choice.kind).contains(needle) {
            return true;
        }
    }
    hex_digits_contain(choice.id, needle)
}

/// The needle a name pick compares with: trimmed, lowercased, and with the
/// "#" / "0x" a user may copy from the screen taken off the front.
pub fn pick_needle(text: &str) -> String {
    let t = filter_needle(text);
    match t.strip_prefix("0x") {
        Some(rest) => alloc::string::ToString::to_string(rest),
        None => t,
    }
}

/// Pixels between the top of a list panel and its first row.
///
/// Four, not ten: the panel is 508px tall and a row is 56, so ten pixels of
/// padding is what made nine rows impossible and left every list at eight even
/// when no warning strip was drawn. Four is the whole of the difference.
pub const LIST_PAD_TOP: i32 = 4;

/// The most rows one list window shows.
pub const LIST_MAX_ROWS: usize = 9;

/// How many rows of a list fit: the window arithmetic every list screen uses.
///
/// strip_lines is the warning / notice strip under the list (0, 1 or 2 lines),
/// and it is what the list gives up a row for - the rule the old code stated in
/// a comment and then made unreachable, because the strip's reserve was already
/// subtracted from the fit and the min(8) on top of it could never bite.
pub fn list_window_rows(body_h: i32, row_h: i32, strip_lines: i32, line_h: i32) -> usize {
    let strip = if strip_lines <= 0 {
        0
    } else {
        strip_lines * line_h + 16
    };
    let usable = (body_h - LIST_PAD_TOP - strip).max(row_h);
    ((usable / row_h).max(1) as usize).min(LIST_MAX_ROWS)
}

/// The tail of a guide line that fits in room, measured by width.
///
/// The guide strip is one line high and the update banner takes its right end,
/// so a long guide is cut - and text_clipped cuts the *end*, which is where
/// the way out ([B] / [＋]) is named. This returns the longest suffix that
/// fits, so what is lost is the beginning of the sentence and never its last
/// item. An empty answer means nothing fits.
pub fn guide_tail<'a>(guide: &'a str, room: i32, width: &mut dyn FnMut(&str) -> i32) -> &'a str {
    if room <= 0 {
        return "";
    }
    if width(guide) <= room {
        return guide;
    }
    let chars: alloc::vec::Vec<(usize, char)> = guide.char_indices().collect();
    for start in 0..chars.len() {
        let tail = &guide[chars[start].0..];
        if width(tail) <= room {
            return tail;
        }
    }
    ""
}

/// "1,606": a count with the thousands grouped.
///
/// The lists this picker shows are four digits long, and 6435 with no break in
/// it is not a number anyone reads at a glance.
pub fn grouped_count(n: usize) -> String {
    let digits = format!("{}", n);
    let mut out = String::new();
    let len = digits.len();
    for (i, ch) in digits.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            out.push(',');
        }
        out.push(ch);
    }
    out
}

/// Sentinel id for "ask for an item name to filter the picker by".
pub const TEXT_ITEM_FILTER: usize = usize::MAX - 1;
/// Sentinel id for "ask for a skill name to filter the picker by".
pub const TEXT_SKILL_FILTER: usize = usize::MAX - 2;
/// Sentinel id for "ask for a quest id or title to filter the list by".
pub const TEXT_QUEST_FILTER: usize = usize::MAX - 3;
