/// Palico なつき度 ceiling.
pub const PALICO_ENTHUSIASM_MAX: u8 = 100;
/// Palico EXP ceiling, the number the bulk MAX writes.
pub const PALICO_EXP_MAX: u32 = 999_999;
/// Brightness byte ceiling.
pub const OPTION_BRIGHTNESS_MAX: u8 = 255;
/// Funds ceiling (also what the bulk MAX writes).
pub const CHAR_FUNDS_MAX: i64 = 9_999_999;
/// HRP ceiling.
pub const CHAR_HRP_MAX: i64 = 99_999_999;
/// Play-time ceiling in seconds, as save::clamp_char allows.
pub const CHAR_PLAYTIME_MAX: i64 = 100_000_000;
/// Hunter rank ceiling as a character field.
pub const CHAR_HR_MAX: i64 = 999;
/// Academy / village point ceiling.
pub const CHAR_POINT_MAX: i64 = 9_999_999;
/// Voice / look byte ceiling.
pub const CHAR_LOOK_MAX: i64 = 255;
/// The character name field is 31 bytes (the game writes up to 10 wide glyphs).
pub const CHAR_NAME_MAX_BYTES: usize = 31;

/// The unit a character row prints after its value.
fn char_unit(field: usize) -> &'static str {
    match field {
        1 => "z",
        2 => "秒",
        3 => "HR",
        4 | 5..=9 => "pts",
        _ => "",
    }
}

/// The first run of digits in `text`, or None.
fn parse_leading_u32(text: &str) -> Option<u32> {
    let digits: alloc::string::String = text
        .trim()
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .collect();
    if digits.is_empty() {
        return None;
    }
    digits.parse::<u32>().ok()
}

/// An equipment id typed by hand: "0x28" in hex, "40" in decimal.
///
/// Hex is the spelling every screen prints for an equipment id, so a number
/// copied off the row works as it stands. A bare number is read as decimal
/// because that is what a bare number means everywhere else in this interface,
/// and `apply_equip_id_text` always re-spells what it took and names it, so a
/// wrong reading is on screen before the write.
fn parse_equip_id(text: &str) -> Option<u16> {
    let t = text.trim();
    let (body, radix) = match t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        Some(hex) => (hex, 16),
        None => (t, 10),
    };
    if body.is_empty() || body.len() > 5 {
        return None;
    }
    u32::from_str_radix(body, radix)
        .ok()
        .map(|v| v.min(u16::MAX as u32) as u16)
}

/// `H:MM` (or a plain second count) as seconds.
///
/// The keyboard answers a time row in the same shape the card prints it, so
/// both `123:45` and `7425` mean the same clock; a value that is not one of the
/// two is refused rather than guessed at.
fn parse_hours_minutes(text: &str) -> Option<u32> {
    let t = text.trim();
    if let Some((h, m)) = t.split_once(':') {
        let hours = parse_leading_u32(h)?;
        let mins = parse_leading_u32(m)?;
        if mins >= 60 {
            return None;
        }
        return Some(hours.saturating_mul(3600).saturating_add(mins * 60));
    }
    parse_leading_u32(t)
}

/// The highest point value the talisman form allows on one skill row.
///
/// The grade's table gives the range and the kind's ceiling tightens it, the
/// same two numbers `charm_form_rows` prints. None means the row cannot hold a
/// value at all (no skill picked, or the kind refuses the second skill).
pub fn charm_points_ceiling(e: &CharmEdit, second: bool) -> Option<i8> {
    let skill = if second { e.skill2 } else { e.skill1 };
    if skill == 0 {
        return None;
    }
    match charm::allowed_points_for_kind(e.kind, skill, second) {
        // "0~0" is the table (or the kind's missing slot 2) refusing the skill:
        // there is no value to jump to.
        Some(r) if r.min == 0 && r.max == 0 => None,
        Some(r) => Some(r.max),
        // Past the end of the talisman tables: the kind's own ceiling is the
        // only answer left.
        None => charm::kind_limits(e.kind).and_then(|l| l.max_points(second)),
    }
}

// ---------------------------------------------------------------------------
// Item box bulk operations
//
// The item screen shows one row per box record; these are the edits that touch
// every record at once. They live here (not in the console UI) so the Switch
// build, the PC build and the tests all run the same code, and so the two rows
// that can drop data can say what they would drop before they run.
// ---------------------------------------------------------------------------

/// The rows of the item box operation menu, opened with [ZR].
///
/// The first four are the requested bulk edits, then the three rows that do not
/// fit that shape: adding through the picker, taking the last edit back, and the
/// name search. Order is menu order; the constants below name the rows.
///
/// The menu itself is [ZR]'s job on the item box: [-] is the delete key and has
/// been since the review that took its nineteen jobs away, and the item box has
/// no other free key (A picks, Y toggles the empty rows, R types the count, X
/// saves, L / R are the BOX tabs, ZL / ZR are the section bar). The name search
/// had [ZR] before this, so it moved in here as a row: the key that opens the
/// menu is one press and the search is two, which is the right way round for a
/// menu that is opened rarely and a list that is 1,500 rows long.
pub const ITEM_OPS: [(&str, &str); 7] = [
    (
        "すべて 99 に",
        "所持している全枠の個数を 99 にそろえます（空き枠はそのまま）",
    ),
    (
        "重複を整理",
        "同じアイテムの枠を1つにまとめます。99 を超えた分は失われます",
    ),
    (
        "空きを詰める",
        "空き枠を後ろへ寄せ、所持品を前から順に並べ直します",
    ),
    (
        "上限を丸める",
        "99 を超えている個数を 99 に戻します（空き枠は触りません）",
    ),
    (
        "アイテムを追加",
        "名前で選んで個数を決め、空き枠へまとめて追加します",
    ),
    (
        "直前の操作を元に戻す",
        "この画面での直前の変更を1つ取り消します",
    ),
    (
        "名前で探す",
        "アイテム名で一覧を絞り込みます（空にすると解除）",
    ),
];

/// "すべて 99 に" - itembox::fill_all.
pub const ITEM_OP_FILL: usize = 0;
/// "重複を整理" - itembox::dedupe, behind a preview and a second press.
pub const ITEM_OP_DEDUPE: usize = 1;
/// "空きを詰める" - itembox::compact.
pub const ITEM_OP_COMPACT: usize = 2;
/// "上限を丸める" - itembox::clamp_counts.
pub const ITEM_OP_CLAMP: usize = 3;
/// "アイテムを追加" - opens the picker in its two-stage add mode (mode 3).
pub const ITEM_OP_ADD: usize = 4;
/// "直前の操作を元に戻す" - pops Editor::item_undo.
pub const ITEM_OP_UNDO: usize = 5;
/// "名前で探す" - the name search that used to be [ZR] on the list itself.
pub const ITEM_OP_FIND: usize = 6;

/// What the operation menu shows next to each row, read from the box once.
///
/// The console redraws this every frame, so the numbers are collected in one
/// pass instead of one decode per row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ItemMenuStats {
    /// Used records below the cap: what "すべて 99 に" would raise.
    pub fill: usize,
    /// Blank records: what "空きを詰める" would close.
    pub holes: usize,
    /// Used records above the cap: what "上限を丸める" would pull down.
    pub over: usize,
    /// What "重複を整理" would free and drop.
    pub dedupe: DedupePreview,
}

impl ItemMenuStats {
    /// The short right-hand text for one menu row, empty when nothing to do.
    pub fn value(&self, op: usize) -> String {
        match op {
            ITEM_OP_FILL if self.fill > 0 => format!("{} 枠", self.fill),
            ITEM_OP_DEDUPE => format!("{} 枠 / {} 個", self.dedupe.freed, self.dedupe.lost),
            ITEM_OP_COMPACT if self.holes > 0 => format!("{} 枠", self.holes),
            ITEM_OP_CLAMP if self.over > 0 => format!("{} 枠", self.over),
            _ => String::new(),
        }
    }
}

/// How many items the box holds in total.
/// An ApplyReport as the lines the panel shows.
///
/// The counts come first because they are the answer to "did it work"; the
/// per-row messages follow, five at most, each clipped to the panel's width.
fn csv_report_lines(report: &crate::csvout::ApplyReport) -> Vec<String> {
    let mut out = Vec::with_capacity(6);
    out.push(alloc::format!(
        "適用 {} 行 / スキップ {} 行 / 丸め {} 行",
        report.applied,
        report.skipped,
        report.clamped
    ));
    for m in report.messages.iter().take(5) {
        out.push(clip_text(m, 60));
    }
    out
}

fn box_total(items: &[ItemSlot]) -> u32 {
    items
        .iter()
        .filter(|s| !s.is_blank())
        .map(|s| s.count as u32)
        .sum()
}

// ---------------------------------------------------------------------------
// Whole save undo
//
// The item box has had its own sixteen step undo since the beginning, but that
// is one box. A step here is the parsed save itself, taken before an edit
// writes it, so every screen that writes the save can take its edit back the
// same way. The depth is four because memory is the thing this console does not
// have: one step is the 4,726,152 byte body plus the 36 byte Switch header
// (4,726,188 bytes, printed as 4.5MB), so four steps cost 18.0MB on top of the
// save that is open.
// ---------------------------------------------------------------------------

/// How many whole-save undo steps the editor keeps.
pub const UNDO_STEPS: usize = 4;

/// Bytes one undo step costs: the Switch header plus the body.
pub const UNDO_STEP_BYTES: usize = crate::save::SWITCH_SIZE;

/// Bytes as the screen prints them, in tenths of a MiB and without floats.
///
/// The arithmetic is integer on purpose: the console build has no libm, and a
/// number the user can check against save::SWITCH_SIZE is worth more than a
/// pretty one. 4,726,188 bytes prints as "4.5MB".
pub fn bytes_mb_text(bytes: usize) -> String {
    let tenths = (bytes as u64 * 10 + (1 << 19)) / (1 << 20);
    format!("{}.{}MB", tenths / 10, tenths % 10)
}

/// What one undo step costs, e.g. "4.5MB".
pub fn undo_step_text() -> String {
    bytes_mb_text(UNDO_STEP_BYTES)
}

/// What the whole stack can cost, e.g. "18.0MB".
pub fn undo_total_text() -> String {
    bytes_mb_text(UNDO_STEP_BYTES * UNDO_STEPS)
}

/// One step of the whole-save undo: the save as it was before an edit.
pub struct SaveUndo {
    /// What the edit was called, for the status line.
    pub label: String,
    /// The slot that was open, put back with the bytes.
    pub slot: usize,
    /// The save before the edit.
    pub save: Save,
}

// ---------------------------------------------------------------------------
// 生データ's byte editor
// ---------------------------------------------------------------------------

/// The state of [A] on 生データ: which byte of the region the caret is on.
///
/// The screen used to be read-only, and the pill on the sub-tab bar promised a
/// 詳細 settings view a user could not change. This is the editor behind that
/// promise, and it is deliberately small: one byte at a time, the confirmation
/// spelled out, and one whole-save undo step per confirmed change.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct MapEdit {
    /// Byte index inside the selected region (0 .. len-1).
    ///
    /// Never leaves the region: [Editor::map_edit_move] clamps at both ends,
    /// because a caret outside the row would be writing a byte the row does not
    /// name and the dump would show it under the wrong offset.
    pub byte: usize,
    /// A change that has been asked for and not confirmed yet.
    ///
    /// The first [◀] / [▶] only *asks*: nothing is written, and the status line
    /// spells out what the second press would do. [A] writes it, [B] drops it.
    pub pending: Option<MapChange>,
}

/// One byte the 生データ editor proposes to change.
///
/// `from` is the byte as it was when the change was armed, so the confirmation
/// can name both sides even after the proposed value has been stepped further.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MapChange {
    /// Offset in the save **body** (not the row).
    pub offset: usize,
    /// The byte as it is now.
    pub from: u8,
    /// What it would become.
    pub to: u8,
}

impl MapChange {
    /// The sentence the task asks for, word for word:
    /// 「オフセット 0x1234 を 0x00 → 0xFF に変えます。よろしいですか」.
    pub fn line(&self) -> String {
        format!(
            "オフセット 0x{:06X} を 0x{:02X} → 0x{:02X} に変えます。よろしいですか（[A] 決定 / [B] 取消）",
            self.offset, self.from, self.to
        )
    }
}

/// Which structural zone a body offset falls in, when it is one.
///
/// The save's body header is not data: +0x00 is the identifier every reader
/// checks, +0x04..+0x10 are the three slot bases and the download-section
/// pointer every other offset is resolved through, and +0x10..+0x28 are
/// reserved. A writer that changes one of them does not edit a record, it
/// moves the ground the records stand on - which is exactly the warning the
/// task asks for, and not a refusal.
pub fn map_offset_zone(body_off: usize) -> Option<&'static str> {
    match body_off {
        0x00 => Some("ヘッダ（セーブの識別子）"),
        0x04..=0x0F => Some("ポインタ（スロット基底 / DLC セクション）"),
        0x10..=0x27 => Some("ヘッダ（予約領域）"),
        _ => None,
    }
}

/// The container header's file-name CRC, as a **file** offset.
///
/// The Switch save's 36 byte header stores crc32(file name) at +0x14; the PC
/// build and the console both read it back to name the file. It is the other
/// checksum-ish zone the task names, and it is not part of the body, so it is
/// classified separately from [map_offset_zone].
pub const MAP_CRC_FILE_OFFSET: usize = 0x14;

/// Which structural zone a **file** offset falls in, when it is one.
///
/// The header itself (0x00..0x24) and, inside it, the file-name CRC.
pub fn map_file_zone(file_off: usize) -> Option<&'static str> {
    if file_off == MAP_CRC_FILE_OFFSET {
        Some("CRC（コンテナヘッダのファイル名）")
    } else if file_off < crate::save::SWITCH_HEADER_SIZE {
        Some("ヘッダ（コンテナヘッダ）")
    } else {
        None
    }
}

/// Hex lines for one stretch of the body, the way [crate::savemap] prints them.
///
/// Sixteen bytes a line with the **body** offset in front, a gap after the
/// eighth byte, and a "… ほか N バイト" tail once the stretch is longer than
/// [crate::savemap::DUMP_BYTES]. This exists for the stretches the table has no
/// row for - the body header - and mirrors savemap::hex_lines exactly, because
/// the header row is drawn in the same panel as the named rows and must not
/// look like a different kind of thing.
fn dump_lines(body: &[u8], offset: usize, len: usize, columns: usize) -> Vec<String> {
    let columns = columns.clamp(1, 32);
    let shown = len.min(crate::savemap::DUMP_BYTES);
    let mut out = Vec::with_capacity(shown / columns + 2);
    for row in (0..shown).step_by(columns) {
        let n = columns.min(shown - row);
        let mut line = format!("{:06X}  ", offset + row);
        for i in 0..n {
            if i == 8 && n > 8 {
                line.push(' ');
            }
            line.push_str(&format!("{:02x} ", body[offset + row + i]));
        }
        while line.ends_with(' ') {
            line.pop();
        }
        out.push(line);
    }
    if len > shown {
        out.push(format!("… ほか {} バイト", len - shown));
    }
    out
}

// ---------------------------------------------------------------------------
// The save layout, for naming what a write changes
//
// Every boundary below is an existing constant from mhnx-core, so the names
// cannot drift away from the offsets the writers use. This table names the
// parts a writer knows (the box, the record, the card); the 183 rows of
// [crate::savemap] name the bytes inside them, and the review prefers whichever
// is narrower, so a change the table cannot name is printed with the map's own
// row instead of "その他". A row neither table covers is still "その他".
//
// The save map is plain table data (`&'static str` names, no once-cell), so it
// is compiled into both builds and the console names records exactly like the
// PC one. This table stays as the fallback for bytes the map does not cover.
// ---------------------------------------------------------------------------

/// One named part of the save.
struct Layout {
    /// Offset from the slot base (slot parts) or from the body start.
    start: usize,
    /// End offset, same base as start.
    end: usize,
    /// What the part holds.
    name: &'static str,
    /// Bytes per record when the part is an array, 0 when it is not.
    unit: usize,
    /// What one record is called, e.g. "枠".
    unit_name: &'static str,
}

